using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Security.Cryptography;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace OpenTPW.Tests;

// Original synthetic standard-field inputs and independent FFmpeg PCM excerpts.
// Complete source/reference hashes and measured envelope: docs/MPEG1-JOINT-REFERENCES.md.
[TestClass]
public class Mpeg1JointReferenceTests
{
	[DataTestMethod]
	[DynamicData( nameof( References ), DynamicDataSourceType.Method )]
	public void IndependentJointPcmExcerptsStayWithinMeasuredEnvelope( string name, string compressedSource, string sourceSha, int rate, int crcChecks, int[] indices, int[] expected )
	{
		using var compressed = new MemoryStream( Convert.FromBase64String( compressedSource ) );
		using var gzip = new GZipStream( compressed, CompressionMode.Decompress );
		using var output = new MemoryStream();
		gzip.CopyTo( output );
		var source = output.ToArray();
		Assert.AreEqual( sourceSha, Convert.ToHexString( SHA256.HashData( source ) ).ToLowerInvariant(), name );
		var audio = Mp2Decoder.Decode( source );
		Assert.AreEqual( rate, audio.SampleRate, name );
		Assert.AreEqual( 2, audio.Channels, name );
		Assert.AreEqual( 4, audio.FrameCount, name );
		Assert.AreEqual( 9216, audio.Samples.Length, name );
		Assert.AreEqual( 0, audio.TrailingBytes, name );
		Assert.AreEqual( crcChecks, audio.CrcChecks, name );
		Assert.AreEqual( 0, audio.CrcFailures, name );
		Assert.AreEqual( indices.Length, expected.Length, name );
		for ( var i = 0; i < indices.Length; i++ )
			Assert.IsTrue( Math.Abs( (int)audio.Samples[indices[i]] - expected[i] ) <= 1, $"{name} PCM[{indices[i]}]: {audio.Samples[indices[i]]}, reference {expected[i]}; measured 1 LSB envelope." );
	}

